], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, proceed to visit Ajmer and Pushkar, famous for their religious significance and as popular pilgrimage centers. You are going to visit a spiritual hub; Ajmer is home to the revered Ajmer Sharif Dargah. Experience the city''s rich religious heritage, bustling markets, and serene Ana Sagar Lake.\nPushkar is renowned for its sacred Pushkar Lake and the Brahma Temple, Pushkar is a vibrant pilgrimage site. Enjoy the lively Pushkar Camel Fair and the town''s bohemian vibe.", "start_time": "09:00", "end_time": "18:00", "travel_distance_km": null, "travel_time_minutes": null, "location": "Pushkar", "hotel_name": null, "room_category": null, "meal_plan": "CP", "breakfast": true, "lunch": false, "dinner": true, "breakfast_hotels": [null, null], "lunch_hotels": [null, null], "dinner_hotels": [null, null], "epai_plan_only": false, "guest_self_booked_hotel": false, "vehicle_type": "AC Car", "pickup_location": null, "drop_location": null, "guide_required": true, "activities": [{"activity_uuid": "4e33eddb-c9bb-5e58-5ea2-5f962e0c73bc", "sort_order": 0, "title": "Dargah of Khwaja Muin-ud-din Chisti at Ajmer", "description": "Sufi mysticism, spiritual sanctuary.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}, {"activity_uuid": "b58ad81a-0604-9e9b-6c87-2c988f925af6", "sort_order": 1, "title": "Lord Brahma Temple at Pushkar", "description": "Sacred sanctum, divine presence.", "start_time": null, "end_time": null, "entry_fee": 0, "guide_required": false}], "images": [], "internal_notes": "", "client_notes": "", "operations_notes": "", "status": "planned", "completion_pct": 0, "packing_tips": "", "things_to_carry": []}, {"day_uuid": "dda3ae64-53fe-364e-89fe-9a560f0fe6d8", "day_number": 4, "day_title": "Pushkar - Chittorgarh - Udaipur", "alternate_day_titles": [], "day_subtitle": null, "day_theme": "Heritage", "day_description": "After breakfast, journey towards Chittorg